package com.primehr.rsp.evaluation.domain;
import com.primehr.rsp.domain.RspAuditedEntity;import jakarta.persistence.*;import org.hibernate.annotations.Nationalized;import java.math.*;
@Entity @Table(name="rsp_comparative_evaluation_item") public class ComparativeEvaluationItem extends RspAuditedEntity{
 @Column(name="comparative_evaluation_id",nullable=false,length=36)private String comparativeEvaluationId;@Column(name="candidate_id",nullable=false,length=36)private String candidateId;@Column(name="total_score",nullable=false,precision=12,scale=4)private BigDecimal totalScore;@Column(name="rank_number",nullable=false)private int rankNumber;@Column(name="tie_group",nullable=false)private int tieGroup;@Nationalized @Column(name="stage_breakdown",nullable=false,length=32000)private String stageBreakdown;@Column(nullable=false)private boolean excluded;@Column(name="exclusion_reason",length=1000)private String exclusionReason;
 protected ComparativeEvaluationItem(){}public ComparativeEvaluationItem(String agency,String evaluation,String candidate,BigDecimal total,int rank,int tie,String breakdown,boolean excluded,String reason){super(agency);comparativeEvaluationId=requiredText(evaluation,"comparativeEvaluationId");candidateId=requiredText(candidate,"candidateId");if(total==null||total.signum()<0||total.compareTo(new BigDecimal("100"))>0||rank<1||tie<1)throw new IllegalArgumentException("Comparative values are invalid");totalScore=total;rankNumber=rank;tieGroup=tie;stageBreakdown=requiredText(breakdown,"stageBreakdown");this.excluded=excluded;exclusionReason=excluded?requiredText(reason,"exclusionReason"):null;}
 public String getComparativeEvaluationId(){return comparativeEvaluationId;}public String getCandidateId(){return candidateId;}public BigDecimal getTotalScore(){return totalScore;}public int getRankNumber(){return rankNumber;}public int getTieGroup(){return tieGroup;}public String getStageBreakdown(){return stageBreakdown;}public boolean isExcluded(){return excluded;}public String getExclusionReason(){return exclusionReason;}
}
